await page.getByRole('button', { name: 'Сохранить', exact: true }).click();
saved = await page.evaluate(() => JSON.parse(localStorage.getItem('orbit-profile-settings')));
assert.ok(saved.avatar.startsWith('data:image/jpeg'));
await page.getByRole('button', { name: 'Удалить', exact: true }).click();
